# bxplaywright PowerShell completions. Generated by `bxplaywright completions powershell`, do not edit.
# Load: bxplaywright completions powershell | Out-String | Invoke-Expression, or add that line to your $PROFILE
Register-ArgumentCompleter -Native -CommandName bxplaywright -ScriptBlock {
	param( $wordToComplete, $commandAst, $cursorPosition )
	$verbs = [ordered]@{
		'clean' = 'Remove the extracted driver and downloaded Node.js (browsers are kept)'
		'codegen' = 'Record browser actions and generate BoxLang code (or --target=java, javascript, python)'
		'completions' = 'Print the tab completion script for bash (default), zsh, fish or powershell'
		'devices' = 'List the device descriptors usable in the device setting'
		'doctor' = 'Check versions, paths, Node.js and browsers, with fix hints'
		'help' = 'Show help for all verbs or one verb'
		'install' = 'Set up the driver and Node.js, then install browsers (default: chromium)'
		'install-deps' = 'Install the operating system packages browsers need (Linux)'
		'install-node' = 'Download the Node.js runtime only (small distribution)'
		'mcp' = 'Start the Playwright MCP server for AI agents'
		'open' = 'Open a headed browser'
		'pdf' = 'Save a URL as PDF (Chromium)'
		'profiles' = 'List profiles, or show one fully resolved'
		'run' = 'Run any Playwright CLI command as-is'
		'screenshot' = 'Take a screenshot of a URL'
		'show-trace' = 'Open the trace viewer'
		'uninstall' = 'Remove installed browsers'
		'version' = 'Show the module, Playwright and Node.js versions'
	}
	$words = @{
		'clean' = @( '--json' )
		'codegen' = @( '--output', '--target', '--device', '--viewport-size', '--load-storage', '--save-storage' )
		'completions' = @( 'bash', 'zsh', 'fish', 'powershell' )
		'devices' = @( '--json' )
		'doctor' = @( '--json' )
		'help' = @( '--json', 'clean', 'codegen', 'completions', 'devices', 'doctor', 'help', 'install', 'install-deps', 'install-node', 'mcp', 'open', 'pdf', 'profiles', 'run', 'screenshot', 'show-trace', 'uninstall', 'version' )
		'install' = @( '--with-deps', '--only-shell', '--force', '--skip-node', '--json', 'chromium', 'firefox', 'webkit', 'chrome', 'chrome-beta', 'msedge', 'all' )
		'install-deps' = @( 'chromium', 'firefox', 'webkit', 'chrome', 'chrome-beta', 'msedge', 'all' )
		'install-node' = @( '--force', '--json' )
		'mcp' = @( '--headless', '--browser', '--port' )
		'open' = @( '--device', '--browser' )
		'pdf' = @( '--paper-format' )
		'profiles' = @( '--json', '4k', 'android', 'android-tablet', 'chrome', 'chrome-beta', 'chromium', 'ci', 'dark', 'debug', 'default', 'desktop', 'edge', 'firefox', 'galaxy', 'hd', 'headed', 'high-contrast', 'ipad', 'iphone', 'iphone-se', 'laptop', 'light', 'macbook', 'mobile', 'mobile-landscape', 'offline', 'pixel', 'print', 'record', 'reduced-motion', 'screenshot', 'tablet', 'webkit' )
		'run' = @(  )
		'screenshot' = @( '--full-page', '--device', '--browser' )
		'show-trace' = @(  )
		'uninstall' = @( '--all' )
		'version' = @( '--json' )
	}
	$elements = @( $commandAst.CommandElements | ForEach-Object { $_.ToString() } )
	if ( $elements.Count -le 1 -or ( $elements.Count -eq 2 -and $wordToComplete ) ) {
		$candidates = @( $verbs.Keys ) + @( '--help', '--version' )
	} else {
		$candidates = $words[ $elements[ 1 ] ]
	}
	$candidates | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
		$tip = if ( $verbs.Contains( $_ ) ) { $verbs[ $_ ] } else { $_ }
		[System.Management.Automation.CompletionResult]::new( $_, $_, 'ParameterValue', $tip )
	}
}
